import React, { useState } from 'react';
import FileUploader from '../components/FileUploader';
import Result from '../components/Result';
import axios from 'axios';

const JAVA_URL = 'http://localhost:8080/api/quizzes';

const QuizPage = () => {
    const [result, setResult] = useState(null);
    const [error, setError] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleFileUpload = async (file) => {
    if (!file) {
        setError("Veuillez sélectionner un fichier valide.");
        return;
    }

    setIsLoading(true);
    setError(null);
    setResult(null);

    try {
        console.log("Lecture du fichier...");
        const text = await file.text();
        console.log("Contenu du fichier:", text);

        const quizData = {
            content: text
        };

        console.log("Envoi de la requête à:", `${JAVA_URL}/generate`);
        const response = await axios.post(`${JAVA_URL}/generate`, quizData, {
            headers: {
                'Content-Type': 'application/json'
            }
        });

        console.log("Réponse reçue:", response.data);

        if (response.data) {
            setResult(response.data);
        } else {
            setError("Aucun quiz généré");
        }
    } catch (error) {
        console.error("Erreur complète:", error);
        setError(error.response?.data || "Erreur lors de la génération du quiz");
    } finally {
        setIsLoading(false);
    }
};

   return (
    <div className="quiz-page">
        <h1>Générer un Quiz</h1>

        <FileUploader
            onUpload={handleFileUpload}
            disabled={isLoading}
            accept=""
        />

        {isLoading && (
            <div className="loading-container">
                <p className="loading-message">Génération du quiz en cours...</p>
            </div>
        )}

        {error && <p className="error-message">{error}</p>}
        {result && <Result data={result} />}
    </div>
);
};

export default QuizPage;
